package main

import (
	"bufio"
	"fmt"
	"io/ioutil"
	"os"
	"strconv"
	"strings"
)

func main() {
	data, _ := ioutil.ReadAll(os.Stdin)
	arr := strings.Split(string(data), "\n")

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	idx := 0
	shift := func() string {
		if idx < len(arr) {
			s := arr[idx]
			idx++
			return s
		}
		idx++
		return ""
	}

	ax := strings.Split(strings.TrimRight(shift(), "\r"), " ")
	v, _ := strconv.Atoi(ax[0])
	e, _ := strconv.Atoi(ax[1])

	if e == 0 {
		fmt.Fprintln(writer, 0)
		return
	}
	if v <= 6 {
		fmt.Fprintln(writer, e)
	} else {
		m := make(map[int][]int)

		for i := 1; i <= v; i++ {
			m[i] = []int{}
		}

		for i := 0; i < e; i++ {
			edge := strings.Split(strings.TrimRight(shift(), "\r"), " ")
			a, _ := strconv.Atoi(edge[0])
			b, _ := strconv.Atoi(edge[1])
			m[a] = append(m[a], b)
			m[b] = append(m[b], a)
		}

		f := false
		noOfVertices := 20
		for j := 1; j <= 7; j++ {
			a7 := m[j]
			for i := 1; i <= 7; i++ {
				if i == j {
					continue
				}
				other := m[i]
				otherSet := make(map[int]bool)
				for _, el := range other {
					otherSet[el] = true
				}
				count := 0
				for _, el := range a7 {
					if otherSet[el] {
						count++
					}
				}
				if count == 0 {
					f = true
					break
				} else if count < noOfVertices {
					noOfVertices = count
				}
			}
		}
		if f {
			fmt.Fprintln(writer, e)
		} else {
			fmt.Fprintln(writer, e-noOfVertices)
		}
	}
}
